def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    V = list(map(int, data[1:N+1]))
    edges = [(int(data[N+i*2]), int(data[N+i*2+1])) for i in range(N-1)]

    return N, V, edges

def build_tree(edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
    return tree

def is_consecutive(jokes):
    if not jokes:
        return True
    sorted_jokes = sorted(jokes)
    return all(sorted_jokes[i] + 1 == sorted_jokes[i+1] for i in range(len(sorted_jokes) - 1))

def count_valid_sets(tree, V, node, parent_jokes):
    if node not in tree:
        return {frozenset([V[node-1]])} if V[node-1] not in parent_jokes else set()

    valid_sets = set()
    for child in tree[node]:
        child_sets = count_valid_sets(tree, V, child, parent_jokes | {V[node-1]})
        for child_set in child_sets:
            new_set = parent_jokes | child_set | {V[node-1]}
            if len(new_set) == len(set(new_set)) and is_consecutive(new_set):
                valid_sets.add(frozenset(new_set))

    if V[node-1] not in parent_jokes:
        valid_sets.add(frozenset({V[node-1]}))

    return valid_sets

