import sys
from collections import defaultdict

def is_consecutive(nums):
    if not nums:
        return True
    nums = sorted(nums)
    return all(b - a == 1 for a, b in zip(nums, nums[1:]))

def count_valid_sets(n, joke_types, supervisors):
    from functools import lru_cache

    # Build the tree
    tree = defaultdict(list)
    for sup, emp in supervisors:
        tree[sup].append(emp)

    @lru_cache(None)
    def dp(node):
        if not tree[node]:
            return {frozenset([joke_types[node-1]])}

        valid_sets = set()
        for child in tree[node]:
            child_sets = dp(child)
            for child_set in child_sets:
                if joke_types[node-1] not in child_set and is_consecutive(list(child_set | {joke_types[node-1]})):
                    valid_sets.add(child_set | {joke_types[node-1]})

        if is_consecutive([joke_types[node-1]]):
            valid_sets.add(frozenset([joke_types[node-1]]))

        return valid_sets

    return len(dp(1))

